package local.tvmorph.tv;
import android.app.*;import android.content.*;import android.os.*;import android.webkit.*;import org.json.*;
public final class TimeUpActivity extends Activity {
 private WebView web;private String id;private final Handler handler=new Handler(Looper.getMainLooper());private static String showing="";
 static boolean open(Context c,String id){if(id.equals(RadioPlayback.ID))RadioPlayback.get(c).stop();if(id.equals(showing))return true;try{showing=id;c.startActivity(new Intent(c,TimeUpActivity.class).putExtra("app",id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP));return true;}catch(RuntimeException ignored){showing="";return false;}}
 protected void onCreate(Bundle state){super.onCreate(state);id=getIntent().getStringExtra("app");if(id==null||ParentalTimer.remaining(this,id)!=0){finish();return;}showing=id;getWindow().setFlags(1024,1024);web=new WebView(this);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setUseWideViewPort(true);web.getSettings().setLoadWithOverviewMode(true);web.addJavascriptInterface(new Bridge(),"ParentPauseNative");web.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}});setContentView(web);web.loadUrl("file:///android_asset/tv/parental-pause.html");}
 private void home(){startActivity(new Intent(this,TvActivity.class).setAction(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_HOME).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_NEW_TASK));finish();}
 public final class Bridge {@JavascriptInterface public String dataJson(){try{String name=id.equals("local.tvmorph.tv.play")?"Morph IPTV":id.equals("local.tvmorph.tv.radio")?"Morph Radio":getPackageManager().getApplicationLabel(getPackageManager().getApplicationInfo(id,0)).toString();return new JSONObject().put("name",name).put("language",UiSettings.language(TimeUpActivity.this)).toString();}catch(Exception e){return "{\"name\":\"Morph TV\",\"language\":\""+UiSettings.language(TimeUpActivity.this)+"\"}";}}@JavascriptInterface public void home(){runOnUiThread(()->TimeUpActivity.this.home());}@JavascriptInterface public void parents(){runOnUiThread(()->AppLocks.timerSettings(TimeUpActivity.this,id));}}
 public void onBackPressed(){home();}
 protected void onResume(){super.onResume();showing=id;handler.postDelayed(check,500);}private final Runnable check=new Runnable(){public void run(){if(isFinishing())return;if(ParentalTimer.remaining(TimeUpActivity.this,id)!=0){finish();return;}handler.postDelayed(this,500);}};
 protected void onPause(){if(id!=null&&id.equals(showing))showing="";handler.removeCallbacks(check);super.onPause();}protected void onDestroy(){if(id!=null&&id.equals(showing))showing="";if(web!=null)web.destroy();super.onDestroy();}
}
